$Core.member = {
	toggleForm: (_this, e) => {
		e.preventDefault();
		var toId = $(_this).attr('toId');
		$('#'+toId).toggleClass('d-none');
		return false;
	}, update_setting_field: (_this, e) => {
		var to_field = $(_this).attr('to_field'),
			def_value = $(_this).attr('def_value'),
			to_value = $(_this).is(':checked') ? 1 : 0;
		$Core.util.toggleIndicatior(1);
		$.post(PCMS_URL+'/index.php?mod=ajax&act=update_setting_field', {
			'to_field' : to_field,
			'def_value' : def_value,
			'to_value' : to_value
		}, function(html){
			$Core.util.toggleIndicatior(0);
		});
	}, view_profile : (_this, e) => {
		e.preventDefault();
		var profile_id = $(_this).attr('profile_id');
		$Core.util.toggleIndicatior(1);
		$.post(path_ajax_script+'/index.php?mod=member&act=view_profile', {
			'profile_id' : profile_id
		}, function(respJson){
			$Core.util.toggleIndicatior(0);
			$(_this).removeClass('clicked');
			var __w = $(window).width();
			if(__w > 1600){
				$Core.popup.openfull(__w/3,respJson.html,respJson.uid);
			} else {
				$Core.popup.openfull(__w/4,respJson.html,respJson.uid);
			}
			$Core.helper.load_list_notes(profile_id, 'Profile', {});
			$Core.member.load_list_files(profile_id, 'Profile', {});
			$('a[data-bs-toggle="tab"]').on('shown.bs.tab', function (e) {
				if($(e.target).hasClass('billing')){
					$Core.member.load_list_billing(profile_id, {});
				} else if($(e.target).hasClass('level_logs')){
					$Core.member.load_level_logs(profile_id, {});
				} else if($(e.target).hasClass('login_logs')){
					$Core.member.load_login_logs(profile_id, {});
				} else{
					var type = $(e.target).data("type");
					$Core.member.load_tab_profile(profile_id, {'type':type});
				} 
			});
			$Core.member.load_list_bank(profile_id, {});
			if(respJson.callback) eval(respJson.callback);
		}, 'json');
		return false;
	}, load_list_bank: (profile_id, options) => {
		var $_adata = options || {};
		$_adata['profile_id'] = profile_id;
		$.post(path_ajax_script+'/index.php?mod=member&act=load_list_bank', $_adata, function(html){
			$Core.util.toggleIndicatior(0);
			$('.holder_bank__'+profile_id).html(html);
		});
	}, open_bank: (_this, e) => {
		e.preventDefault();
		var _bank_id = $(_this).attr('bank_id'),
			_profile_id = $(_this).attr('profile_id');
		$Core.util.toggleIndicatior(1);
		$.post(path_ajax_script+'/index.php?mod=member&act=open_bank', {
			'bank_id' : _bank_id,
			'profile_id' : _profile_id
		}, function(respJson){
			$Core.util.toggleIndicatior(0);
			$Core.popup.open('auto','auto', respJson.html, `open_bank__${respJson.uid}`);
		}, 'json');
		return false;
	}, delete_bank: (_this, e) => {
		e.preventDefault();
		var _bank_id = $(_this).attr('bank_id'),
			_profile_id = $(_this).attr('profile_id');
		$Core.messager.confirm("Thông báo", "Bạn chắc chắn muốn xoá?", () => {
			$Core.util.toggleIndicatior(1);
			$.post(path_ajax_script+'/index.php?mod=member&act=delete_bank', {
				'bank_id' : _bank_id,
				'profile_id' : _profile_id
			}, function(html){
				$Core.util.toggleIndicatior(0);
				$Core.member.load_list_bank(profile_id, {});
			});
		});
		return false;
	}, pop_save_bank: (_this, e) => {
		e.preventDefault();
		var _validated = 0,
			_form = $(_this).closest('form'),
			bank_id = $(_this).attr('bank_id'),
			profile_id = $(_this).attr('profile_id');
		if($('input.required,select.required', _form).length){
			$('input.required,select.required', _form).each((_i, _elem) => {
				if($Core.util.isEmpty($(_elem).val())){
					_validated++;
					$(_elem).focus();
					return false;
				}
			});
		}
		if(_validated==0){
			$Core.util.toggleIndicatior(1);
			_form.ajaxSubmit({
				type: "POST",
				url: path_ajax_script+"/index.php?mod=member&act=pop_save_bank",
				data: {'bank_id': bank_id, 'profile_id':profile_id},
				dataType: "html",
				success: function(html){
					$Core.util.toggleIndicatior(0);
					if(html.indexOf('_success') >= 0){
						$Core.member.load_list_bank(profile_id, {});
						$('.btn-close', _form).trigger('click');
					} else {
						$Core.messager.alert('Error!', 'Đã xảy ra lỗi hệ thông.');
					}
				}
			});
		}
		return false;
	}, editInlineField: (_this, options) => {
		var $_adata = options || {},
			p_id= $(_this).attr('p_id'),
			p_field= $(_this).attr('p_field'),
			p_cell = $(_this).closest('.InputCRMHandler');
		p_cell.html('<img src="'+URL_IMAGES+'/ripple-loading.svg" />');
		$.post(path_ajax_script+'/index.php?mod=member&act=load_edit_inline_field', $_adata, function(html){
			p_cell.html(html);
			setTimeout(() => {
				$('.edit_profile_field_'+p_field+'_'+p_id).focus();
			}, 500);
		});
		return false;
	}, save_edit_inline_field: (_this, e) => {
		e.preventDefault();
		var _more = {},
			_body = $(_this).closest('.modal-body')
			,p_id= $(_this).attr('p_id'),
			p_field= $(_this).attr('p_field'),
			p_cell = $(_this).closest('.InputCRMHandler');
		//alert(p_value); return false;
		if(p_field == 'issue_date'){
			var p_value = "";
			$('.edit_profile_field_'+p_field+'_'+p_id, _body).each((_i, _elem) => {
				p_value += (_i == 0 ? "" : "||") + $(_elem).val();
			});
		} else {
			var p_value = $('.edit_profile_field_'+p_field+'_'+p_id, _body).val();
		}
		$Core.util.toggleIndicatior(1);
		$.post(path_ajax_script+'/index.php?mod=member&act=load_edit_inline_field', $.extend(_more, {
			'p_id' : p_id,
			'p_field' : p_field,
			'p_value' : p_value,
			'p_action' : '_save'
		}), function(html){
			$Core.util.toggleIndicatior(0);
			if(html.indexOf('_error_code') >= 0){
				$Core.messager.alert('Thông báo', 'Mã nhân viên đã tồn tại !');
			} else if(html.indexOf('_error_email') >= 0){
				$Core.messager.alert('Thông báo', 'Địa chỉ email này đã tồn tại !');
			} else {
				p_cell.html(html);
			}
		});
		return false;
	}, cancel_edit_inline_field: (_this, e) => {
		e.preventDefault();
		var p_id= $(_this).attr('p_id'),
			p_field= $(_this).attr('p_field'),
			p_cell = $(_this).closest('.InputCRMHandler');
		p_cell.html('<img src="'+URL_IMAGES+'/ripple-loading.svg" />');
		$.post(path_ajax_script+'/index.php?mod=member&act=load_edit_inline_field', {
			'p_id' : p_id,
			'p_field' : p_field,
			'p_action' : '_cancel'
		}, function(html){
			p_cell.html(html);
		});
		return false;
	}, load_list_files:  (for_id, clsTable, options) => {
		var $_adata = options || {};
		$_adata['for_id'] = for_id;
		$_adata['clsTable'] = clsTable;
		$.post('/index.php?mod=member&act=load_list_files', $_adata, function(respJson){
			$('.holder_files_'+for_id).html(respJson.html);
		}, 'json');
	}, ms_save_file: (_this, e) => {
		e.preventDefault();
		var _validated = 0,
			$_form = $(_this).closest('form'),
			for_id = $(_this).attr('for_id'),
			clsTable = $(_this).attr('clsTable');
		if($('input.required,textarea.required', $_form).length){
			$('input.required,textarea.required', $_form).each((_i, _elem) => {
				if($Core.util.isEmpty($(_elem).val())){
					_validated++;
					$(_elem).focus();
					return false;
				}
			});
		}
		if(_validated==0){
			$Core.util.toggleIndicatior(1);
			$_form.ajaxSubmit({
				type: 'POST',
				url: '/index.php?mod=member&act=ms_save_file',
				data: {'for_id':for_id, 'clsTable':clsTable},
				dataType: 'html',
				success: function (html) {
					$Core.util.toggleIndicatior(0);
					if(html.indexOf('_success') >= 0){
						$_form[0].reset();
						$Core.member.load_list_files(for_id, clsTable, {});
					}else{
						$Core.messager.alert("Error!",'Upload failed !');
					}
				}
			});
		}
		return false;
	}, save_profile_pfield: (_this, e) => {
		e.preventDefault();
		var _form = $(_this).closest('form'),
			profile_id = $(_this).attr('profile_id');
		$Core.util.toggleIndicatior(1);
		_form.ajaxSubmit({
			type: "POST",
			url: PCMS_URL + "/index.php?mod="+MOD+"&act=save_profile_pfield",
			data: { 'profile_id': profile_id },
			dataType: "json",
			success: function(respJson) {
				$Core.util.toggleIndicatior(0);
				if(respJson.msg.indexOf('_success') >= 0){
					if($('.'+respJson.p_field+'_'+profile_id).length){
						$('.'+respJson.p_field+'_'+profile_id).text(respJson.p_value);
					}
					$Core.messager.alert('Thông báo', 'Cập nhật thành công!');
				} else {
					$Core.messager.alert('Thông báo', 'Cập nhật thất bại!');
				}
			}
		});
		return false;
	}, load_list_billing: (profile_id, options) => {
		var $_adata = options || {};
		$_adata['profile_id'] = profile_id;
		$.post('/index.php?mod=member&act=load_list_billing', $_adata, function(respJson){
			$('.holder_billing_'+profile_id).html(respJson.html);
			if(parseInt(respJson.total_record) > 0){
				if(parseInt(respJson.total_page) > 1){
					$('#pager_staff_building_'+respJson.uid).addClass('mt-2').pagination({
						listStyle:"pagination justify-content-center",
						currentPage: respJson.current_page, 
						itemsOnPage: respJson.per_page,
						items: respJson.total_record,
						cssStyle: 'light-theme',
						prevText : '<i class="tf-icon bx bx-chevrons-left"></i>',
						nextText : '<i class="tf-icon bx bx-chevrons-right"></i>',
						onPageClick : function(pageNumber){
							$Core.member.load_list_billing(profile_id, $.extend(options, {'page':pageNumber}), false);
						}
					});
				}
			}
		}, 'json');
	}, load_tab_profile: (profile_id, options) => {
		var $_adata = options || {},
			type = options["type"];
		$_adata['profile_id'] = profile_id;
		$.post('/index.php?mod=member&act=load_tab_profile', $_adata, function(respJson){
			$('.holder_'+type+'_'+profile_id).html(respJson.html);
			if(parseInt(respJson.total_record) > 0){
				if(parseInt(respJson.total_page) > 1){
					$('#pager_'+type+'_'+respJson.uid).addClass('mt-2').pagination({
						listStyle:"pagination justify-content-center",
						currentPage: respJson.current_page, 
						itemsOnPage: respJson.per_page,
						items: respJson.total_record,
						cssStyle: 'light-theme',
						prevText : '<i class="tf-icon bx bx-chevrons-left"></i>',
						nextText : '<i class="tf-icon bx bx-chevrons-right"></i>',
						onPageClick : function(pageNumber){
							$Core.member.load_tab_profile(profile_id, $.extend(options, {'page':pageNumber}), false);
						}
					});
				}
			}
		}, 'json');
	}, load_level_logs: (profile_id, options) => {
		var $_adata = options || {};
		$_adata['profile_id'] = profile_id;
		$.post('/index.php?mod=member&act=load_level_logs', $_adata, function(respJson){
			$('.holder_level_logs_'+profile_id).html(respJson.html);
		}, 'json');
	}, load_login_logs: (profile_id, options) => {
		var $_adata = options || {};
		$_adata['profile_id'] = profile_id;
		$.post('/index.php?mod=member&act=load_login_logs', $_adata, function(respJson){
			$('.holder_login_logs_'+profile_id).html(respJson.html);
		}, 'json');
	}, file_explorer: (_this, e) => {
		e.preventDefault();
		var toId = $(_this).attr('toId');
		$('#'+toId).trigger('click');
		return false;
	}, file_upload: (_this, e) => {
		let file, files = $(_this).prop('files');
		if (files && files.length) {
			file = files[0];
			if (/^image\/\w+/.test(file.type)) {
				var toImg = $(_this).attr('toImg'),
					profile_id = $(_this).attr('profile_id'),
					params = {"profile_id":profile_id, 'toImg':toImg};
				$Core.member.do_upload(file, params);
			}
		}
	}, do_upload: (file, params) => {
		var URL = window.URL || window.webkitURL,
			imgdata = URL.createObjectURL(file),
			filename = $.trim(file.name),
			$_adata = params || {};
		$_adata['filename'] = filename;
		$_adata['imgdata'] = imgdata;
		$Core.util.toggleIndicatior(1);
		$.post(path_ajax_script+'/index.php?mod=member&act=open_cropper', $_adata, function(respJson){
			$Core.util.toggleIndicatior(0);
			$Core.popup.open('auto', 'auto', respJson.html, 'open_cropper_'+respJson.uid);
			$('#open_cropper_'+respJson.uid).on('shown.bs.modal', function(){
				var $cropper = $('#'+'cropper_'+respJson.uid),
					options = { aspectRatio: (4 / 4)},
					originalImageURL = $cropper.attr('src'),
					uploadedImageName = 'cropped.png',
					uploadedImageType = 'image/png',
					uploadedImageURL, $target;
				$cropper.cropper(options);
				$('.ui-cropper-tool').on('click', function(e){
					$Core.util.stopEventHandler(e);
					var $_this = $(this),
						data = $_this.data(),
						cropper = $cropper.data('cropper');
					if (cropper && data.method) {
						data = $.extend({}, data); // Clone a new one
						if (typeof data.target !== 'undefined') {
							$target = $(data.target);
							if (typeof data.option === 'undefined') {
								try {
									data.option = JSON.parse($target.val());
								} catch (e) {
									console.log(e.message);
								}
							}
						}
						cropped = cropper.cropped;
						switch (data.method) {
							case 'getCroppedCanvas':
								if (uploadedImageType === 'image/jpeg') {
									if (!data.option) {
										data.option = {};
									}
									data.option.fillColor = '#fff';
								}
								break;
						}
						var result = $('#cropper_'+respJson.uid).cropper(data.method, data.option);
						switch (data.method) {
							case 'getCroppedCanvas':
								if (result) {
									var imagedata = result.toDataURL(uploadedImageType),
										imgdata = imagedata.replace(/^data:image\/(png|jpg);base64,/, ""),
										$_bdata = params || {};
									$_bdata['imgdata'] = imgdata;
									$_bdata['filename'] = filename;
									$.post('/index.php?mod=member&act=upload_avatar',$_bdata,function(html){
										$('#'+'frmCropper')[0].reset();
										$cropper.cropper('destroy');
										$Core.popup.close($('#open_cropper_'+respJson.uid));
										if(html.indexOf('_error') >= 0){
											$Core.messager.alert(__['Message'], __['Image upload error']);
										} else {
											var tmp = html.split('|||');
											$('#'+params.toImg).attr('src', tmp[1]);
										}
									});
									return false;
								}
								break;
							case 'destroy':
								if (uploadedImageURL) {
									URL.revokeObjectURL(uploadedImageURL);
									uploadedImageURL = '';
									$image.attr('src', originalImageURL);
								}
								break;
						}
						if (typeof result === 'object' && result !== cropper && $target) {
							try {
								$target.value = JSON.stringify(result);
							} catch (e) {
								console.log(e.message);
							}
						}
					}
					return false;
				});
			});
		}, 'json');
	}, open: (_this, e) => {
		e.preventDefault();
		$Core.util.toggleIndicatior(1);
		$.post('/index.php?mod='+MOD+'&act=open', {}, function(respJson) {
			$Core.util.toggleIndicatior(0);
			$Core.popup.open('auto','auto',respJson.html, `open_create_new_${respJson.uid}`);
		}, 'json');
		return false;
	}, add_new: (_this, e) => {
		e.preventDefault();
		var _validated = 0,
			_form = $(_this).closest('form');
		
		if($('input.required, select.required').length){
			$('input.required, select.required').each((_i, _elem) => {
				if($Core.util.isEmpty($(_elem).val())){
					_validated++;
					$(_elem).focus();
					var message = $(_elem).data('val-required');
					$Core.alert.error(message);
					return false;
				}
			});
		}
		if(_validated == 0){
			$Core.util.toggleIndicatior(1);
			_form.ajaxSubmit({
				type: "POST",
				url: PCMS_URL + "/index.php?mod="+MOD+"&act=add_new",
				data: { 'profile_id': profile_id },
				dataType: "json",
				success: function(respJson) {
					$Core.util.toggleIndicatior(0);
					if(respJson.msg.indexOf('_success') >= 0){
						$Core.messager.alert('Thông báo', 'Thêm mới thành công!');
						setTimeout(() => {
							window.location.reload();
						}, 1000);
					} else {
						$Core.messager.alert('Thông báo', respJson.html_error);
					}
				}
			});
		}
		return false;
	}, handle_dept_changed: (_this, e) => {
		$Core.util.toggleIndicatior(1);
		var _form = $(_this).closest('form');
		$.post('/index.php?mod='+MOD+'&act=handle_dept_changed', {
			'department_id' : $(_this).val()
		}, function(respJson) {
			$Core.util.toggleIndicatior(0);
			$('select[name=role_id]', _form).html(respJson.html_role_options);
			$('select[name=team_id]', _form).html(respJson.html_team_options);
		}, 'json');
	}, select_team: (_this, e) => {
		$Core.util.toggleIndicatior(1);
		var _form = $(_this).closest('form');
		$.post('/index.php?mod='+MOD+'&act=get_team_options', {
			'department_id' : $(_this).val()
		}, function(respJson) {
			$Core.util.toggleIndicatior(0);
			$('select[name=team_id]', _form).html(respJson.html_team_options);
		}, 'json');
	}, save_zalo_send_config: (_this, e) => {
		e.preventDefault();
		var _error = 0,
			_form = $(_this).closest("form"),
			profile_id = $(_this).attr('profile_id');
		if($('textarea.required:visible,input.required:visible', _form).length){
			$('textarea.required:visible,input.required:visible', _form).each((_i, _elem) => {
				if($Core.util.isEmpty($(_elem).val())){
					_error++;
					$(_elem).focus();
					return false;
				}
			});
		}
		if(_error==0){
			$Core.util.toggleIndicatior(1);
			_form.ajaxSubmit({
				type:'POST',
				url: PCMS_URL + "/index.php?mod=member&act=save_zalo_send_config",
				data: {'profile_id' : profile_id},
				dataType: "json",
				success: function(respJson){
					$Core.util.toggleIndicatior(0);
					if(respJson.msg.indexOf('_success') >= 0) {
						alertify.success("Thêm mới nhóm nhân viên thành công");
					}else{
						alertify.error("Có lỗi xảy ra. Vui lòng thử lại!");
					}
				}
			});
		}else{
			alertify.error("Vui lòng nhập đủ thông tin!");
		}
		return false;
	}, open_social_channels: (_this, e) => {
		e.preventDefault();
		var profile_id = $(_this).attr('profile_id');
		$Core.util.toggleIndicatior(1);
		$.post(PCMS_URL + '/index.php?mod=member&act=open_social_channels', {
			'profile_id': profile_id
		}, function(respJson){
			$Core.util.toggleIndicatior(0);
			$Core.popup.open('auto', 'auto', respJson.html, respJson.uid);
			$('#' + respJson.uid).on('hidden.bs.modal', function(){ $(this).remove(); });
		}, 'json');
		return false;
	}, add_social_row: (_this, e) => {
		e.preventDefault();
		var form = $(_this).closest('form'),
			profile_id = $(_this).attr('profile_id');
		var html = '<div class="social-channel-row d-flex gap-2 align-items-center mb-2">'
			+ '<select class="form-select" name="category" style="width:150px;flex:0 0 150px">'
			+ '<option value="tiktok">TikTok</option>'
			+ '<option value="youtube">Youtube</option>'
			+ '<option value="fanpage">Fanpage</option>'
			+ '<option value="facebook">Facebook</option>'
			+ '</select>'
			+ '<input type="text" class="form-control" name="title" placeholder="Tiêu đề" style="flex:1">'
			+ '<input type="text" class="form-control" name="link" placeholder="Link" style="flex:2">'
			+ '<a href="javascript:void(0);" class="btn btn-icon btn-outline-default" onclick="$(this).parent().remove()"><i class=\'bx bx-trash\'></i></a>'
			+ '</div>';
		$('#social_channels_' + profile_id, form).append(html);
		return false;
	}, save_social_channels: (_this, e) => {
		var rows = [],
			modal = $(_this).closest('.modal'),
			profile_id = $(_this).attr('profile_id');
		$('.social-channel-row', modal).each((_i, _elem) => {
			var link = $(_elem).find('[name="link"]').val().trim();
			if(link) rows.push({
				category: $(_elem).find('[name="category"]').val(),
				title: $(_elem).find('[name="title"]').val().trim(),
				link: link
			});
		});
		$Core.util.toggleIndicatior(1);
		$.ajax({
			url: PCMS_URL + '/index.php?mod=member&act=save_social_channels',
			type: 'POST',
			data: {profile_id: profile_id, social_channels: JSON.stringify(rows)},
			dataType: 'json',
			success: function(res){
				$Core.util.toggleIndicatior(0);
				if(res.msg === '_success'){
					alertify.success('Lưu thành công!');
					$(_this).closest('.modal').find('.btn-close').trigger('click');
					var rowsHtml = '';
					rows.forEach(function(r){
						var catIcon  = {tiktok:'bxl-tiktok',youtube:'bxl-youtube',fanpage:'bxl-facebook-square',facebook:'bxl-facebook'};
						var catColor = {tiktok:'text-dark',youtube:'text-danger',fanpage:'text-primary',facebook:'text-primary'};
						var catLabel = {tiktok:'TikTok',youtube:'Youtube',fanpage:'Fanpage',facebook:'Facebook'};
						var icon  = catIcon[r.category]  || 'bx-globe';
						var color = catColor[r.category] || '';
						var label = catLabel[r.category] || r.category;
						var name  = r.title ? r.title : label;
						rowsHtml += '<div class="col-12 col-sm-6">'
							+ '<a href="' + r.link + '" target="_blank" class="d-flex align-items-center gap-2 p-2 border rounded text-decoration-none">'
							+ '<i class="bx ' + icon + ' fs-3 flex-shrink-0 ' + color + '"></i>'
							+ '<div class="flex-grow-1 overflow-hidden">'
							+ '<div class="fw-medium small">' + name + '</div>'
							+ '<div class="text-muted text-truncate" style="font-size:11px">' + r.link + '</div>'
							+ '</div></a></div>';
					});
					var html = rows.length
						? '<div class="row g-2">' + rowsHtml + '</div>'
						: '<p class="text-muted py-1 mb-0 small">Chưa có kênh nào</p>';
					$('.holder_social_channels_' + profile_id).html(html)
				}
			}
		});
	},

}